//! A learning-path Exercise, through the scoring the app really has.
//!
//! `tests/path_fixtures/schedules.jsonl` is generated by `npm run paths -- gen`
//! from the packs in `src/paths/packs/`: every Exercise with target notes, as the
//! exact `ScoreSchedule` that `src/songs/schedule.ts` builds. This proves that
//! format reaches `match_attempt` and comes out meaning what it should. It says
//! **nothing about a real guitar**: the "played" onsets here are computed, with a
//! little seeded jitter, because the question is whether the Exercise is scorable,
//! not whether the detector hears it.
//!
//!   node scripts/rust-test.mjs --test path_exercises

use std::fs;
use std::path::PathBuf;

use yames_lib::instrument::Instrument;
use yames_lib::score::{
    match_attempt, BeatMap, OnsetState, PlayedOnset, ScheduleReport, ScoreSchedule,
};
use yames_lib::session_log::Xorshift64;

#[derive(serde::Deserialize)]
struct Row {
    path: String,
    exercise: String,
    bpm: f64,
    schedule: ScoreSchedule,
}

fn rows() -> Vec<Row> {
    let file = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("path_fixtures")
        .join("schedules.jsonl");
    fs::read_to_string(&file)
        .unwrap_or_else(|e| panic!("{}: {e}. Run: npm run paths -- gen", file.display()))
        .lines()
        .map(|line| serde_json::from_str(line).expect("a schedule the app can read"))
        .collect()
}

fn beat_map(bpm: f64, beats: f64) -> BeatMap {
    let ms = 60_000.0 / bpm;
    BeatMap::from_quarter_times((0..=(beats.ceil() as usize + 1)).map(|i| i as f64 * ms).collect())
}

/// Every written onset, played at its time plus up to `jitter_ms` either way.
fn played(row: &Row, jitter_ms: f64, seed: u64) -> Vec<PlayedOnset> {
    let ms = 60_000.0 / row.bpm;
    let mut rng = Xorshift64::new(seed);
    row.schedule
        .onsets
        .iter()
        .map(|onset| PlayedOnset {
            time_ms: onset.beat * ms + ((rng.next_u64() % 2001) as f64 / 1000.0 - 1.0) * jitter_ms,
            amplitude: if onset.accent { 1.0 } else { 0.5 },
            confidence: 1.0,
        })
        .collect()
}

fn report(row: &Row, notes: &[PlayedOnset]) -> ScheduleReport {
    let weights = Instrument::ElectricGuitar.profile().score_weights;
    match_attempt(
        &row.schedule,
        &beat_map(row.bpm, row.schedule.length_beats),
        notes,
        &weights,
    )
}

fn hits(report: &ScheduleReport) -> usize {
    report
        .results
        .iter()
        .filter(|r| r.state == OnsetState::Hit)
        .count()
}

fn misses(report: &ScheduleReport) -> usize {
    report
        .results
        .iter()
        .filter(|r| r.state == OnsetState::Miss)
        .count()
}

#[test]
fn every_exercise_is_scorable_and_the_right_playing_passes() {
    let rows = rows();
    assert!(rows.len() > 80, "only {} schedules", rows.len());
    for (index, row) in rows.iter().enumerate() {
        let report = report(row, &played(row, 2.0, 1 + index as u64));
        let name = format!("{}/{}", row.path, row.exercise);
        assert_eq!(
            hits(&report),
            row.schedule.onsets.len(),
            "{name}: all written notes played, all should be hits"
        );
        assert_eq!(report.extras.len(), 0, "{name}: nothing extra was played");
        assert!(
            report.hit_completeness > 0.99,
            "{name}: hit completeness {}",
            report.hit_completeness
        );
        assert!(
            report.interval_consistency >= 0.85,
            "{name}: evenness {} at 2 ms of jitter should clear the 0.85 bar",
            report.interval_consistency
        );
    }
}

/// The pass bars use `hit_completeness` because the headline `score` ignores it
/// on guitar. If that ever changes this test still holds, and it is the reason
/// a pass bar may not be written against `score`.
#[test]
fn a_dropped_picked_note_shows_up_in_the_field_a_pass_bar_uses() {
    let mut checked = 0;
    for (index, row) in rows().iter().enumerate() {
        let picked: Vec<usize> = row
            .schedule
            .onsets
            .iter()
            .enumerate()
            .filter(|(_, o)| !o.soft)
            .map(|(i, _)| i)
            .collect();
        if picked.len() < 8 {
            continue;
        }
        let drop = picked[picked.len() / 2];
        let mut notes = played(row, 2.0, 100 + index as u64);
        notes.remove(drop);
        let report = report(row, &notes);
        let name = format!("{}/{}", row.path, row.exercise);
        assert!(misses(&report) >= 1, "{name}: a dropped note must be a miss");
        assert!(
            report.hit_completeness < 1.0,
            "{name}: hit completeness {} should fall",
            report.hit_completeness
        );
        checked += 1;
    }
    assert!(checked > 60, "only {checked} Exercises long enough to test");
}

#[test]
fn an_extra_note_shows_up_as_an_extra() {
    let rows = rows();
    let row = rows
        .iter()
        .find(|r| r.exercise == "even-eighths.open-string")
        .expect("the first Exercise of Alternate Picking");
    let mut notes = played(row, 1.0, 7);
    // Halfway between two written eighths.
    let ms = 60_000.0 / row.bpm;
    notes.push(PlayedOnset {
        time_ms: 1.25 * ms,
        amplitude: 0.5,
        confidence: 1.0,
    });
    notes.sort_by(|a, b| a.time_ms.partial_cmp(&b.time_ms).unwrap());
    let report = report(row, &notes);
    assert_eq!(report.extras.len(), 1);
}

#[test]
fn an_unheard_hammer_on_costs_nothing() {
    let rows = rows();
    let row = rows
        .iter()
        .find(|r| r.exercise == "two-strings.pentatonic-lick")
        .expect("a two-string sweep lick with a hammer and two pulls");
    let mut notes = played(row, 1.0, 11);
    let soft: Vec<usize> = row
        .schedule
        .onsets
        .iter()
        .enumerate()
        .filter(|(_, o)| o.soft)
        .map(|(i, _)| i)
        .collect();
    assert_eq!(soft.len(), 3);
    for index in soft.iter().rev() {
        notes.remove(*index);
    }
    let report = report(row, &notes);
    assert_eq!(misses(&report), 0, "soft notes are never a miss");
    assert_eq!(
        report
            .results
            .iter()
            .filter(|r| r.state == OnsetState::SoftAbsent)
            .count(),
        3
    );
}

#[test]
fn a_constant_input_delay_is_the_known_limit_at_speed() {
    // The audit's defect 2, on one of our own Exercises: this pins it so whoever
    // adds calibration has a test that changes and a reason to re-read
    // `gradingLimits`. A slow Exercise survives a 50 ms lag; sixteenths at a
    // brisk tempo should lose notes. Should this assertion start failing because
    // calibration landed, the fast rungs can be trusted further: update both.
    let rows = rows();
    let slow = rows
        .iter()
        .find(|r| r.exercise == "even-eighths.open-string")
        .unwrap();
    let mut late = played(slow, 2.0, 21);
    late.iter_mut().for_each(|n| n.time_ms += 50.0);
    let report_slow = report(slow, &late);
    assert_eq!(hits(&report_slow), slow.schedule.onsets.len());
    assert!(report_slow.interval_consistency >= 0.85);

    let fast = rows
        .iter()
        .find(|r| r.exercise == "speed-bursts.one-beat")
        .unwrap();
    let mut late = played(fast, 2.0, 22);
    late.iter_mut().for_each(|n| n.time_ms += 60.0);
    let report_fast = report(fast, &late);
    assert!(
        hits(&report_fast) < fast.schedule.onsets.len(),
        "sixteenths at {} BPM with 60 ms of delay kept every note: calibration may have landed",
        fast.bpm
    );
}
